function immutable(c:BuildingComponent){const i=F110_IDS.find(i=>i.city===c.city&&i.objectId===c.objectId&&i.partId===c.partId),s=SOURCE[c.partId];return !!i&&!!s&&nativePaintSignature(c)===i.signature&&JSON.stringify(c.origin)===JSON.stringify(s.origin)&&JSON.stringify(c.componentGeometry)===JSON.stringify(s.componentGeometry)&&JSON.stringify(c.sourceFeature)===JSON.stringify(s.sourceFeature)&&c.batches.length===s.batches.length&&c.batches.every((b,bi)=>['positions','normals','indices','color'].every(k=>{const a=(b as any)[k],e=s.batches[bi][k];return a?.length===e.length&&Array.from(a as ArrayLike<number>).every((v,j)=>Object.is(v,e[j]));}));}
export function ownerF110Reconstruction(components:BuildingComponent[]):{components:BuildingComponent[];stats:OwnerReconstructionStats}{const stats:OwnerReconstructionStats={objects:0,vertices:0,triangles:0,originalVertices:0,sourceRetained:true,actualVisualAccepted:false,components:[]};if(!components.some(c=>c.city==='cologne'&&ownerF110Identity(c)))return{components,stats};const duplicates=F110_IDS.some(i=>components.filter(c=>c.city===i.city&&c.objectId===i.objectId&&c.partId===i.partId).length>1);if(duplicates){stats.error='F110 duplicate native carrier';return{components,stats};}return{components:components.map(c=>{if(c.city!=='cologne'||!ownerF110Identity(c))return c;if(!immutable(c)){stats.error='F110 unchanged native carrier required';return c;}const batches=DISPLAY[c.partId].map(b=>({...b,positions:[...b.positions],normals:[...b.normals],indices:[...b.indices],color:[...b.color],frames:[...b.frames],paint:[...b.paint],writeMask:[...b.writeMask]}));const vertices=batches.reduce((s,b)=>s+b.positions.length/3,0),triangles=batches.reduce((s,b)=>s+b.indices.length/3,0);if(vertices)stats.objects++;stats.vertices+=vertices;stats.triangles+=triangles;stats.originalVertices+=c.batches.reduce((s,b)=>s+b.positions.length/3,0);stats.components.push({objectId:c.objectId,partId:c.partId,sourcePartId:c.partId,patchSHA256:F110_RECONSTRUCTION_SHA,vertices,triangles,geometryRole:'owner-authorized-reconstruction'});return{...c,batches,displayEstimates:{...c.displayEstimates,F110Exterior:{sourceRetained:true,sourceOnlyAlias:false,patchSHA:F110_RECONSTRUCTION_SHA,originalNativeGettersUnchanged:true,photoAndSourceDerivedDisplay:true,notFormalBuildingGroup:true,allVerticalDatumsExplicitDisplayEstimates:true,availableViewportSubsetReconstructedIndependently:true,wholeSourceEvidenceExpected28:true}}};}),stats};}
export function ownerF110BaseMaterials(components:BuildingComponent[],paint:Float32Array,frames:Float32Array){let offset=0,objects=0,vertices=0;for(const c of components){const match=c.city==='cologne'&&ownerF110Identity(c)&&!!c.displayEstimates?.F110Exterior;if(match)objects++;for(const b of c.batches){const count=b.positions.length/3;if(match){const a=b as Batch;for(let j=0;j<count;j++)if(a.writeMask[j]){paint.set(a.paint.slice(j*4,j*4+4),4*(offset+j));frames.set(a.frames.slice(j*5,j*5+5),5*(offset+j));vertices++;}}offset+=count;}}return{objects,vertices,actualVisualAccepted:false};}
